content.text:
        c->st[29]++;
        return 0;
    }
    if (!c->emit(c->user, rank, frame, len)) {
        c->st[29]++;
        return 0;
    }
    c->st[is_data ? 20 : 21]++;
    return 1;
}

static int send_upstream_ack(collector_t *c, int rank, uint32_t prefix)
{
    const epic_port_t *port = &c->ports[rank];
    uint32_t psn = (c->start + prefix - 1u) & MASK24;
    size_t len = epic_build_roce_ack(c->frame, c->frame_cap, port->switch_mac,
                                      port->host_mac, port->switch_ip,
                                      port->host_ip, UDP_PORT, UDP_PORT,
                                      port->host_qpn, psn);
    return emit_frame(c, rank, c->frame, len, 0);
}

static int send_result(collector_t *c, int rank, uint32_t q)
{
    const uint8_t *payload = NULL;
    size_t payload_len = 0;
    uint32_t p = q;
    const slot_t *s = NULL;

    switch (c->primitive) {
    case EPIC_PRIM_ALLGATHER: {
        uint32_t local = q / 3u;
        int src = rank_from_ordinal(rank, (int)(q % 3u));
        p = local;
        s = slot_find(c, p);
        if (!s || !s->raw[src]) {
            return 1; /* nothing to retransmit */
        }
        payload = s->raw[src];
        payload_len = (size_t)c->D * 4u;
        break;
    }
    case EPIC_PRIM_BCAST: {
        p = q;
        s = slot_find(c, p);
        if (!s || !s->raw[c->root]) {
            return 1;
        }
        payload = s->raw[c->root];
        payload_len = (size_t)c->D * 4u;
        break;
    }
    case EPIC_PRIM_BARRIER: {
        p = 0;
        s = slot_find(c, p);
        if (!s) {
            return 1;
        }
        payload = NULL;
        payload_len = 0;
        break;
    }
    case EPIC_PRIM_REDUCESCATTER: {
        p = (uint32_t)rank * (c->K / 4u) + q;
        s = slot_find(c, p);
        if (!s) {
            return 1;
        }
        break;
    }
    default: {
        p = q;
        s = slot_find(c, p);
        if (!s) {
            return 1;
        }
        break;
    }
    }

    if (c->primitive == EPIC_PRIM_ALLREDUCE || c->primitive == EPIC_PRIM_REDUCE ||
        c->primitive == EPIC_PRIM_REDUCESCATTER) {
        size_t bytes = (size_t)c->D * 4u;
        memset(c->scratch, 0, bytes);
        if (c->D) {
            for (uint32_t j = 0; j < c->D; j++) {
                uint32_t v = s->agg[j];
                c->scratch[4u * j + 0u] = (uint8_t)(v >> 24);
                c->scratch[4u * j + 1u] = (uint8_t)(v >> 16);
                c->scratch[4u * j + 2u] = (uint8_t)(v >> 8);
                c->scratch[4u * j + 3u] = (uint8_t)v;
            }
        }
        payload = c->scratch;
        payload_len = bytes;
    }

    const epic_port_t *port = &c->ports[rank];
    uint32_t psn = (c->start + q) & MASK24;
    size_t len = epic_build_roce_data_raw(c->frame, c->frame_cap, port->switch_mac,
                                          port->host_mac, port->switch_ip,
                                          port->host_ip, UDP_PORT, UDP_PORT,
                                          port->host_qpn, psn, payload,
                                          payload_len);
    return emit_frame(c, rank, c->frame, len, 1);
}

static int result_ready(const collector_t *c, int rank, uint32_t q)
{
    uint32_t p = q;
    switch (c->primitive) {
    case EPIC_PRIM_ALLGATHER:
        p = q / 3u;
        break;
    case EPIC_PRIM_REDUCESCATTER:
        p = (uint32_t)rank * (c->K / 4u) + q;
        break;
    case EPIC_PRIM_BARRIER:
        p = 0;
        break;
    default:
        break;
    }
    const slot_t *s = slot_find(c, p);
    if (!s) {
        return 0;
    }
    if (c->primitive == EPIC_PRIM_BCAST) {
        return (s->mask & (uint8_t)(1u << c->root)) != 0;
    }
    return s->complete != 0;
}

